def longestRepeatingSubsequence(s):
    n = len(s)
    prev = [0] * (n + 1)
    for i in range(1, n + 1):
        cur = [0] * (n + 1)
        c = s[i - 1]
        for j in range(1, n + 1):
            if c == s[j - 1] and i != j:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = cur[j - 1] if cur[j - 1] > prev[j] else prev[j]
        prev = cur
    return prev[n]
